examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
MonarchResizablePanels(
    fraction = fraction,
    onFractionChange = { fraction = it },
    modifier = Modifier
        .height({{height}}.dp)
        .clip(MonarchTheme.shapes.lg)
        .border(MonarchTheme.spacing.px, MonarchTheme.colors.borderDefault, MonarchTheme.shapes.lg),
    range = ({{panels.0.minSize}}f / 100f)..({{panels.0.maxSize}}f / 100f),
    showGrip = true,
    first = {
        Box(Modifier.fillMaxSize().padding(MonarchTheme.spacing.space3)) {
            MonarchText(text = {{panels.0.label}})
        }
    },
    second = {
        Box(Modifier.fillMaxSize().padding(MonarchTheme.spacing.space3)) {
            MonarchText(text = {{panels.1.label}})
        }
    },
)
MonarchText(
    text = "Saved layout: ${(fraction * 100).roundToInt()} / ${100 - (fraction * 100).roundToInt()}",
    style = MonarchTextStyle.Caption,
)
}

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
MonarchResizablePanels(
    fraction = fraction,
    onFractionChange = { fraction = it },
    modifier = Modifier
        .height(240.dp)
        .clip(MonarchTheme.shapes.lg)
        .border(MonarchTheme.spacing.px, MonarchTheme.colors.borderDefault, MonarchTheme.shapes.lg),
    range = (20f / 100f)..(50f / 100f),
    showGrip = true,
    first = {
        Box(Modifier.fillMaxSize().padding(MonarchTheme.spacing.space3)) {
            MonarchText(text = "Folders")
        }
    },
    second = {
        Box(Modifier.fillMaxSize().padding(MonarchTheme.spacing.space3)) {
            MonarchText(text = "Messages")
        }
    },
)
MonarchText(
    text = "Saved layout: ${(fraction * 100).roundToInt()} / ${100 - (fraction * 100).roundToInt()}",
    style = MonarchTextStyle.Caption,
)
}

MonarchResizablePanels(
    fraction = fraction,
    onFractionChange = { fraction = it },
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 3),
    axis = MonarchResizablePanelsAxis.Vertical,
    range = 0.2f..0.8f,
    onResizeFinished = { saved = it },
    first = { Box(Modifier.fillMaxWidth().heightIn(min = MonarchTheme.spacing.space16).padding(MonarchTheme.spacing.space3)) { MonarchText(text = "Query") } },
    second = {
        Box(Modifier.fillMaxWidth().heightIn(min = MonarchTheme.spacing.space16).background(MonarchTheme.colors.bgSubtle).padding(MonarchTheme.spacing.space3)) {
            MonarchText(text = "Results")
        }
    },
)
